
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lb_N_2_vrho():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lb", 2)
    if not feval._have_vxc:
        pytest.skip("build lacks the derivative order for vrho")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=feval._have_vxc, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["vrho"])
    tgt = out["vrho"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.717032365326174e+00, -6.717535729535999e+00, -6.610278879429761e+00, -6.611010963675812e+00, -6.460476712496515e+00, -6.461548322941478e+00, -6.252515762857172e+00, -6.254101708784124e+00, -5.968199390535008e+00, -5.970592398648775e+00, -5.587770960726195e+00, -5.591509613960226e+00, -5.093637168453884e+00, -5.099856415135262e+00, -4.476609306206245e+00, -4.488152390982387e+00, -3.741879553312637e+00, -3.767384168023154e+00, -2.901264821976795e+00, -2.971134514521389e+00, -1.938335879462960e+00, -2.117421566559142e+00, -1.140372981943866e+00, -1.081885021383624e+00, -9.744454135204907e-01, -6.619481259203045e-01, -8.720026703758881e-01, -6.566377638729249e-01, -6.861256231659550e-01, -5.392606368807615e-01, -4.785306790492198e-01, -3.828705026218756e-01, -3.041049137108742e-01, -2.516528976637418e-01, -1.863260305258899e-01, -1.660041180672349e-01, -1.201009429836495e-01, -1.154072745884577e-01, -8.312479476966035e-02, -8.148997156912191e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-05


